using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class OlgaTokarczuk
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Moje dzieła są wystarczająco dobrze zrobione, żeby żyć, ale też tak niedoskonałe, żeby nic ze swojego życia nie rozumieć. Przykro mi, że nie mogą być szczęśliwi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Mówić do kogoś, kto nie rozumie, to próbować otworzyć zamek źdźbłem trawy, to kroić chleb gałązką bazylii, wkręcać żarówkę w ptasie gniazdo, wkładać dyskietkę między dwa kamienie. Daremnie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wszystko zdarza się tylko raz i my sami jesteśmy jednorazowi. Nie było nas, zanim się urodziliśmy, i nie będzie nas, gdy umrzemy, Raj to cyfrowy sen. Nikt nas nie wybawi, nie naprawi, nie zadośćuczyni.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zgubiła ją własna duma; to jedyny grzech bogów.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Celem mojej pielgrzymki jest zawsze inny pielgrzym.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Gdyby można było spojrzeć na świat bez żadnej ochrony, uczciwie i odważnie – pękłyby nam serca.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Prześwietlić świat jak rentgenem i ujrzeć tam szkielet-Pustki.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Och, ludzie ciągle potrzebują rzeczy niezwykłych, cudów, szaleństw. I po co? Żeby z jeszcze większą gorliwością akceptować swoje zwyczajne życie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Skoro jest prawo i porządek, musi być także coś, co to prawo dopełnia i ogranicza zarazem – chaos i nieistnienie. Nieistnienie i chaos.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Tu i teraz jesteśmy ślepi i nigdy nie wiemy, co jest naprawdę ważne.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Rewolucje nie lubią wariatów, bo same są śmiertelnie poważne.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wszystko jest zawsze prostsze, niż się na początku wydaje.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zdaje się, że nic nie budzi wśród mężczyzn takiego współczucia jak samotna kobieta.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "A ponieważ Żydzi ciągle się boją – myśli Moliwda – a to pana, a to Kozaka, a to niesprawiedliwości, głodu i chłodu, przez co żyją w wielkiej niepewności, to Jakub staje się dla nich wybawieniem. Brak lęku jest niczym aureola – można się w niej grzać, można zapewnić trochę ciepła małej, zziębniętej, wystraszonej duszy.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Aszer Rubin uważa, że większość ludzi jest głupia i że to głupota ludzka sprowadza na świat smutek. Nie jest to grzech ani cecha, z którą człowiek się rodzi, ale zły pogląd na świat, błędna ocena tego, co widzą oczy. W rezultacie ludzie spostrzegają wszystko osobno, każdą rzecz w oderwaniu od pozostałych. Prawdziwa mądrość to sztuka łączenia wszystkiego ze wszystkim, wtedy wyłania się prawdziwy kształt rzeczy.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Dobrze jest nie rozumieć języka, nie rozumieć zwyczajów, sunąć jak duch pomiędzy innymi, którzy są dalecy i nierozpoznawalni. Wtedy budzi się szczególna mądrość – umiejętność domysłu, chwytania spraw nieoczywistych. Budzą się też wówczas bystrość i przenikliwość. Człowiek, który jest obcy, zyskuje nowy punkt widzenia, staje się, chcąc nie chcąc, swoistym mędrcem (…) Tylko obcy naprawdę rozumie, czym jest świat.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Gdy przepisujemy i cytujemy, budujemy gmach wiedzy i rozmnażamy ją jak moje warzywa czy jabłonki. Przepisywanie jest jak szczepienie drzewa; cytowanie – jak wysiewanie nasion.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Istnieje także teoria Lynn Margualis, znanej amerykańskiej biolożki, która mówi, że źródłem ewolucyjnych innowacji są nie tylko przypadkowe mutacje, lecz również symbiogeneza, czyli symbiotyczne scalanie się łańcuchów komórek bakteryjnych. Margualis twierdzi, że do powstania nowych gatunków doprowadziły endosymbioza szeregowa oraz połączone przetrwanie – przykładem są mitochondria, które kiedyś funkcjonowały jako osobne organizmy i które zostały wcielone do komórek lub połączyły się z nimi, odtąd pracując na ich rzecz. Margualis pokazuje, że organizmy żywe nie tylko walczą i współzawodniczą, ale także oddziałują na siebie i łącząc się, wspierają wzajemnie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Kiedy wierzono, że świat jest płaski, był on płaski: nie podróżowało się za morza, nie wykraczało poza krańce. Dla geocentrycznego Układu Słonecznego zrobiono całkiem przekonujące rachunki matematyczne, które miały pragmatyczne zastosowanie – można było przewidywać zaćmienia i sprawnie konstruować kalendarze. Nasz umysł za wszelką cenę wspiera to, w co wierzymy. Właśnie dlatego tak trudno jest zmienić świat.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Największy paradoks empatii: porzucając siebie, mamy być może jedyną szansę stać się czymś, co jest naszym przeciwieństwem. Skoro obcość nie jest, jak by się tego oczekiwało, radykalna, traci swoją magiczną, zagrażającą moc. Obcy staje się kimś, kogo można pojąć i zrozumieć. Właściwie przestaje być obcym. Nie ma swoich i obcych. Wszyscy jesteśmy swoi, więc każde zło, jakie wyrządzamy innym, wyrządzamy sobie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Nasza komunikacja jest o tyle istotna i głęboka, o ile pozostaje wzajemną wymianą tego, co subiektywne, a więc nie do końca komunikowalne. (…) Tylko fikcja literacka jest w stanie opowiedzieć taki stan subiektywności człowieka (a zarazem jego pełni), tylko fikcja z jej możliwościami zbudowania całej osoby ma przewagę nad argumentami rozumu (a więc nad tradycyjną formą intelektualnego wykładu).", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Pokazać darkroom to dokonać rewelacji, odkryć to, co ukryte. I szybko wychodzi na wierzch dziwna dwuznaczność seksu. Podkreśla to swoista estetyka tych przestrzeni, która budzi trudną do powstrzymania pokusę dezynfekcji – kafelki na podłodze i ścianach, tapicerka ze skaju; coś pomiędzy łaźnią, rzeźnią i sklepem mięsnym. Skąd to? Dlaczego nie rajski ogród, arkadia, natura, alkowa?<br />Skoro seks jest naturalny, dlaczego wydaje ma się taki nienaturalny, obcy, wstydliwy? Dlaczego wolimy darkroomy, a nie lightroomy? Postulowanie wyzwolenia seksualnego nie na wiele się przydało.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Skoro można pomyśleć, że może być lepiej, to znaczy, że już jest lepiej.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "W zachodnich filmach dokumentalnych o polskim rolnictwie z wielkim upodobaniem i w długich sekwencjach pokazuje się furmanki. Jest podejrzenie, że ich wypożyczaniem zajmuje się jakaś firma logistyczna.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Widzimy więc te same rzeczy w inny sposób. Widzimy co innego i czasem bywa to bolesne. (…) Życie społeczne, kontakty z innymi, nauka, media, sztuka – to drobiazgowe, mozolnie uzgadniane „prawdy”. Całe epoki mają swoje „prawdy”, które po czasie rozsypują się w pył. Mają też swoje „prawdy” poszczególne jednostki; niektóre z nich aktualne przez całe życie, inne podlegają kolejnym weryfikacjom. (…) Subiektywne poczucie prawdy wiążę się zawsze z aktem oceny. Jest to świadomy akt woli – uznaję, że coś jest prawdziwe, i na dodatek przyjmuje konsekwencje tej oceny. To rodzaj dobrowolnego przykrojenia doświadczenia do pewnego wzoru. Jest to konieczne, o ile mamy żyć we wspólnym poznawczo i etycznie świecie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wierzę, że uznawanie czegoś za oczywiste wcale nie wiąże się z kwestią faktów, lecz raczej umowy społecznej i przyzwyczajeń naszego umysłu, tym samym należy bardziej do dziedziny psychologii niż fizyki.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "(…) jakikolwiek pomysł na przewidywanie przyszłości budzi w ludziach fascynację i jednocześnie wielki irracjonalny opór. Powoduje też klaustrofobiczny lęk przed fatum, z którym ludzkość zmaga się od czasów Edypa. W gruncie rzeczy ludzie nie chcą znać przyszłości.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "(…) emocje zawsze są prawdziwe, nieprawdziwa może być ich przyczyna. Emocje wzbudzane przez fałszywe przyczyny są równie silne, jak te powodowane przez prawdziwe, dlatego często wyprowadzają człowieka w pole. Trzeba je po prostu przeżyć.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wielka skorupa ślimaka, która zwija się do wewnątrz. W środku jest królestwo, tym doskonalsze i szczęśliwsze, im głębiej wejdzie w niego bohaterka. Ta spirala nie ma końca, wkręca się w nieskończoność, a istoty, które w niej zamieszkują, są po prostu coraz mniejsze, lecz nie mniej doskonałe. Wędrując w głąb, idzie się w nieskończoność i doskonałość. Świat jest skorupą, porusza się poprzez czas na ogromnym ślimaku.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wojna to jest fenomen straszliwy, piekielny – nawet jeżeli siedzib ludzkich nie dotykają same walki, to ona i tak rozchodzi się wszędzie, pod najlichszą strzechę, głodem, chorobą, strachem powszechnym. Serca twardnieją, obojętnieją. Zmienia się całe ludzkie myślenie – każdy dba tylko o siebie i baczy, jak tu samemu przetrwać. Niejeden robi się przy tym okrutny i nieczuły na cudze cierpienie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Bóg jest w każdym procesie. Bóg pulsuje w przemianach. Raz jest, raz jest go mniej, ale czasem nie ma go wcale. Bóg bowiem przejawia się nawet w tym, że go nie ma.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Człowiek jest istotą głupią, która musi się uczyć. Dokleja więc do siebie wiedzę, zbiera ją jak pszczoła i ma jej coraz więcej, użytkuje ją i przetwarza. Ale to w środku, co jest „głupie” i potrzebuje nauki, nie zmienia się.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Kto raz widział granice świata, ten najboleśniej doświadczać będzie swego uwięzienia.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Ludzie – którzy sami są przecież procesem – boją się tego, co niestałe i zawsze zmienne, dlatego wymyślili coś, co nie istnieje – niezmienność, i uznali, że to, co wieczne i niezmienne, jest doskonałe.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Ludzie myślą, że żyją bardziej intensywnie niż zwierzęta, niż rośliny, a tym bardziej – niż rzeczy. Rośliny śnią, że żyją bardziej intensywnie niż rzeczy. A rzeczy trwają, i to trwanie jest bardziej życiem niż cokolwiek innego.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Młodość w swoim natężeniu, w swojej mocy, męczy się sobą. Którejś nocy czy któregoś poranka człowiek przechodzi granice, osiąga swój szczyt i robi pierwszy krok w dół ku śmierci.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Może młynki do kawy są osią rzeczywistości?", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Myślał, że starość otwiera to trzecie okno, którym widzi się wszystko na wskroś, które pozwala rozumieć, jak działa świat. Ale nic się nie wyjaśniło.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Największym oszustwem młodości jest wszelki optymizm, uporczywa wiara w to, że we wszystkim jest postęp.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Nie ma nikogo takiego, o kim można by powiedzieć, że wymyślił młynek, tworzenie jest bowiem tylko przypominaniem sobie tego co istnieje poza czasem, czyli od zawsze. Człowiek nie potrafi stwarzać z niczego, to boska umiejętność.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "W niewiedzy, że się istnieje jest wyzwolenie od czasu i śmierci.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Byli to rzeczywiście ludzie ze studni – tacy, co wpadli do niej dawno temu i teraz na jej dnie urządzali sobie swoje życie, myśląc, że studnia jest całym światem.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Czasami, gdy Człowiek doświadcza Gniewu, wszystko wydaje się oczywiste i proste. Gniew zaprowadza porządek, pokazuje świat w oczywistym skrócie, w Gniewie powraca też dar Jasności Widzenia, o który trudno w innych stanach.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Historie życia nie są tematem do dyskusji. Powinno się ich wysłuchać i zrewanżować się tym samym.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "(…) ludzie w naszym kraju nie mają umiejętności zrzeszania się i tworzenia wspólnoty (…). To kraj neurotycznych indywidualistów, z których każdy, gdy tylko znajdzie się wśród innych, zaczyna ich pouczać, krytykować, obrażać i okazywać im swoją niewątpliwą wyższość.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "My mamy światopogląd, a Zwierzęta światoczucie, wiesz?", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Najlepiej rozmawia się samemu ze sobą. Przynajmniej nie dochodzi do nieporozumień.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Ranki zimowe zrobione są ze stali, mają metaliczny smak i ostre krawędzie. W środę o siódmej rano, w styczniu, widać, że świat nie został stworzony dla Człowieka, a na pewno nie ku jego wygodzie i przyjemności.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Smutek jest ważnym słowem w definicji świata. Leży u podstaw wszystkiego, jest piątym żywiołem, kwintesencją.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wielu mężczyzn z wiekiem zapada na autyzm testosteronowy, który przejawia się w powolnym zaniku inteligencji społecznej i umiejętności międzyludzkiej komunikacji, a także upośledza formułowanie myśli. Zaatakowany tą Dolegliwością Człowiek staje się milczący i wydaje się pogrążony w rozmyślaniach. Bardziej interesują go różne Narzędzia i maszynerie. Pociągają go druga wojna światowa i biografie znanych ludzi, najczęściej polityków i złoczyńców. Prawie zanika jego zdolność do czytania powieści, autyzm testosteronowy zaburza psychologiczne rozumienie postaci.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Więzienie nie tkwi na zewnątrz, ale jest w środku każdego z nas. Może jest tak, że nie umiemy bez niego żyć.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wszystko przeminie. Mądry Człowiek wie o tym od samego początku i niczego nie żałuje.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Z punktu widzenia natury nie ma istot pożytecznych i niepożytecznych. To tylko niemądre rozróżnienie stosowane przez ludzi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zdrowie jest stanem niepewnym i nie wróży nic dobrego. Lepiej jest być sobie spokojnie chorym, wtedy przynajmniej wiemy, na co umrzemy.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Brakuje nam języka, brakuje punktów widzenia, metafor, mitów i nowych baśni. Jesteśmy za to świadkami, jak te nieprzystające, zardzewiałe i anachroniczne stare narracje próbuje się wprzęgnąć do wizji przyszłości, może wychodząc z założenia, że lepsze stare coś niż nowe nic, albo próbując w ten sposób poradzić sobie z ograniczeniem własnych horyzontów. Jednym słowem – brakuje nam nowych sposobów opowiadania o świecie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Czułość jest tą najskromniejszą odmianą miłości. To ten jej rodzaj, który nie pojawia się w pismach ani w ewangeliach, nikt na nią nie przysięga, nikt się nie powołuje. Nie ma swoich emblematów ani symboli, nie prowadzi do zbrodni ani zazdrości. Pojawia się tam, gdzie z uwagą i skupieniem zaglądamy w drugi byt, w to, co nie jest „ja”.<br />Czułość jest spontaniczna i bezinteresowna, wykracza daleko poza empatyczne współodczuwanie. Jest raczej świadomym, choć może trochę melancholijnym współdzieleniem losu. Czułość jest głębokim przejęciem się drugim bytem, jego kruchością, niepowtarzalnością, jego nieodpornością na cierpienie i działanie czasu.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Jan Amos Komenski, wielki pedagog XVII wieku, ukuł termin „pansofia”, w którym zawarł idee możliwej omniscjencji, wiedzy uniwersalnej, która pomieści w sobie wszelkie możliwe poznanie. Było to także i przede wszystkim marzenie o wiedzy dostępnej każdemu. Czyż dostęp do informacji o świecie nie zmieni niepiśmiennego chłopa w refleksyjną jednostkę świadomą siebie i świata? Czy wiedza na wyciągnięcie ręki nie sprawi, że ludzie staną się rozważni i mądrze pokierują swoim życiem? Kiedy powstał Internet wydawało się, że idee te będą wreszcie mogły zrealizować się w sposób totalny. Wikipedia, którą podziwiam i wspieram, mogłaby wydać się Komenskiemu, podobnie jak wielu myślicielom tego nurtu, spełnieniem marzeń ludzkości – oto tworzymy i otrzymujemy ogromny zasób wiedzy nieustannie uzupełnianej, odświeżanej i demokratycznie dostępnej, praktycznie z każdego miejsca na Ziemi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Literatura jest jedną z niewielu dziedzin, które próbują nas przytrzymać przy konkrecie świata, ponieważ ze swej natury jest zawsze „psychologiczna”. Skupia się bowiem na wewnętrznych racjach i motywach postaci, ujawnia ich doświadczenie w żaden inny sposób niedostępne dla drugiego człowieka lub zwyczajnie prowokuje czytelnika do psychologicznej interpretacji ich zachowań. Tylko literatura jest w stanie pozwolić nam wejść głęboko w życie drugiej istoty, rozumieć jej racje, dzielić jej uczucia, przeżyć jej los.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Możemy mieć dziś wielką satysfakcję, że jesteśmy świadkami powstania nowego sposobu opowiadania świata, jaki niesie ze sobą serial filmowy, a którego ukrytym zadaniem jest wprowadzić nas w trans. Oczywiście ten sposób opowiadania istniał już w mitach i opowieściach homeryckich, a Herkules, Achilles czy Odyseusz to bez wątpienia pierwsi serialowi bohaterowie. Jednak nigdy wcześniej nie zagarnął on dla siebie tak dużo przestrzeni i nie wpływał tak istotnie na zbiorową wyobraźnię.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Parafraza Szekspirowskiego cytatu jak nigdy pasuje dzisiaj do tej kakofonicznej rzeczywistości: internet to coraz częściej opowieść idioty pełna wściekłości i wrzasku.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Szept świata umilkł, zastąpiły go hałasy miasta, szmer komputerów, grzmot przelatujących nad głową samolotów i męczący biały szum oceanów informacji. Od jakiegoś momentu w swoim życiu zaczynamy widzieć świat we fragmentach, wszystko osobno, w kawałkach odległych od siebie niczym galaktyki, a rzeczywistość, w jakiej żyjemy, w tym nas upewnia: lekarze leczą nas według specjalności, podatki nie mają związku z odśnieżaniem drogi, którą jeździmy do pracy, obiad nijak się ma do wielkich ferm hodowlanych, a nowa bluzka do obskurnych fabryk gdzieś w Azji. Wszystko jest od siebie oddzielone, żyje osobno, bez związku.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Świat umiera, a my nawet tego nie zauważamy. Nie zauważamy, że świat staje się zbiorem rzeczy i wydarzeń, martwą przestrzenią, w której poruszamy się samotni i zagubieni, miotani czyimiś decyzjami, zniewoleni niezrozumiałym fatum, poczuciem bycia igraszką wielkich sił historii czy przypadku. Nasza duchowość zanika albo staje się powierzchowna i rytualna. Albo po prostu stajemy się wyznawcami prostych sił – fizycznych, społecznych, ekonomicznych – które poruszają nami, jakbyśmy byli zombi. I w takim świecie rzeczywiście jesteśmy zombi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zalew obrazów przemocy, głupoty, okrucieństwa, mowy nienawiści rozpaczliwie równoważone są przez wszelkie „dobre wiadomości”, ale nie są one w stanie ujarzmić dojmującego wrażenia, które trudno jest nawet zwerbalizować: coś jest ze światem nie tak. To poczucie, zarezerwowane kiedyś tylko dla neurotycznych poetów, dziś staje się epidemią nieokreśloności, sączącym się zewsząd niepokojem.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Alfred Whitehead mówił, że religia to najgłębszy rodzaj lojalności wobec świata. Herezja zaś – dodałabym – to najgłębszy rodzaj kontestacji. Każda herezja niesie ze sobą jakąś ideę zmiany świata.Dekonstrukcja obowiązującej wiary natychmiast prowadzi do nowych projektów na życie i istnienie społeczeństwa, do rewindykacji starych pojęć i zastąpienia ich nowymi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Było cudownie, bardzo się wzruszyłam. Patrząc na te dzieci – kolorowe, w różnych ubraniach, witające mnie w różnych swoich językach – pomyślałam, jakie to bogactwo sobie Szwecja przygarnęła wraz z imigrantami. Jaki to jest potencjał różnych sposobów myślenia, wrażliwości, puli genetycznej. I podziwiam też, że jest taka biblioteka, w której te dzieci mają dostęp do książek, że się je uczy (…), że się coś robi. I po prostu zawsze w takich momentach jest mi po prostu wstyd za ten straszny 2014 rok, kiedy Polska nie przyjęła imigrantów. Nigdy nie potrafię tego zrozumieć.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Czułam się tak, jakby jakieś niezależne siły zgłaszały swój akces do opisywanej przeze mnie historii, jakby sprzęgły się jakieś moce i niosły pomoc. Jakby światu zależało na napisaniu tej książki.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Jak wygląda świat, kiedy życie staje się tęsknotą? Wygląda papierowo, kruszy się w palcach, rozpada. Każdy ruch przygląda się sobie, każda myśl przygląda się sobie, każde uczucie zaczyna się i nie kończy, i w końcu sam przedmiot tęsknoty robi się papierowy i nierzeczywisty. Tylko tęsknienie jest prawdziwe, uzależnia. Być tam, gdzie się nie jest, mieć to, czego się nie posiada, dotykać kogoś, kto nie istnieje. Ten stan ma naturę falującą i sprzeczną w sobie. Jest kwintesencją życia i jest przeciwko życiu. Przenika przez skórę do mięśni i kości, które zaczynają odtąd istnieć boleśnie. Nie boleć. Istnieć boleśnie – to znaczy, że podstawą ich istnienia był ból. Toteż nie ma od takiej tęsknoty ucieczki. Trzeba by było uciec poza własne ciało, a nawet poza siebie. Upijać się? Spać całe tygodnie? Zapamiętywać się w aktywności aż do amoku? Modlić się nieustannie?", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Katolicyzm nie sprzyja odwadze myślenia, eksperymentowaniu z ideami, jest zachowawczy i ostrożny. Zmiany w jego obrębie następują powoli i w sytuacji, kiedy już nie można dalej obstawać przy swoim. Taki klimat sprzyja dwóm filarom polskiej kultury religijnej – konformizmowi i hipokryzji.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Może to zabrzmi nieco ekscentrycznie w naszych bardzo pragmatycznych czasach, ale starałam się zawsze tak ustawić moją pracę, żeby miała jakiś rodzaj sensu, żeby mnie budowała, i żeby przynosiła choćby odrobinę dobra dla innych. Nic wielkiego, ale wtedy rzeczywiście praca staje się praktyką. (…) Właściwie nie umiem już robić nic jak tylko pisać, i to jest wyjątkowa praca, właściwie ukochane hobby, które stało się pracą. Najlepsza z możliwości.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "My, ludzie Zachodu mamy wdrukowany leciutki odcień pogardy dla politeizmu jako czegoś bardziej prymitywnego, lecz można spojrzeć na to i tak, że w tej oszałamiającej różnorodności kultów wyraża się niepojęta dla człowieka natura ''sacrum''.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Nie ma chyba doskonalszej, cudownie i sensownie wzniesionej przez wieki czy nawet tysiąclecia przed-nauki. W całości opiera się na innej niż naukowa, racjonalna i empiryczna, podstawie. To dogłębna praca intuicji, obserwacji, używająca innej części umysłu. Opowiadana językiem mitów, ten język na dodatek ciągle się rozwija i wielu ludzi uważa, że astrologia całkiem dobrze działa także w naszych czasach.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Obraz naszej historii, który mamy w głowie, jest jak zamek z papieru. Wygląda imponująco, ale palcem można wywiercić w nim dziurę. Potrzeba nam więc historycznej herezji.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Pogarda do tego, co nienaukowe, w katolickim społeczeństwie powinna dziwić. Kwestionuje się istnienie wpływu Księżyca na człowieka – jego siła porusza miliardami hektolitrów wody w oceanach – wierząc jednocześnie w dużo bardziej irracjonalne rzeczy, np. poczęcie z ducha czy powstanie z martwych.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Polscy sędziowie, jesteśmy świadomi tego, w jakiej wielkiej teraz opresji żyjecie, jak jesteście zwalniani z pracy, przesuwani na inne stanowiska, jak bardzo cierpią na tym wasze rodziny. I chcę powiedzieć wam tylko, że jesteśmy z Wami.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Praca jest najuczciwszym stosunkiem do rzeczywistości.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Stara tradycja sabbatajska głosiła, że kiedy Mojżesz schodził z góry Horeb z kanonem moralnym danym od Boga człowiekowi na kamiennych tablicach, ujrzał, że jego lud oddał się wszelkiemu możliwemu rozpasaniu i głupocie. Uznał wtedy, że człowiek nie zasłużył na tak szczodre i wielkoduszne potraktowanie przez Boga i rozbił boskie tablice. W zamian – napisał swoje własne przykazania, obmyślone po to, żeby trzymać ludzi w karności, niewoli, posłuszeństwie i narzuconym prostackim reżimie moralnym.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Starość to czas dawania. Jesteś jak jabłonka obwieszona jabłkami, które już tobie są niepotrzebne. Nieważne jest już rozmnażanie się, tylko żeby obdzielić innych tym, co masz i historiami, wspomnieniami, myślami.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "To, co w horrorach cenię i lubię, to wyrwanie człowieka z jego metafizycznego samozadowolenia i poczucia, że jest w stanie wszystko kontrolować. Horror pełni dziś rolę trochę religijną – przypomina, że można człowieka postrzegać w wymiarach innych niż ten materialny i realistyczny. Że są siły, których nie kontrolujemy i z którymi musimy się zmierzyć. Dobry horror to taki, który sprawia poczucie niewygody egzystencjalnej, która czasami budzi lęk, a czasami zostawia nas z refleksją, że świat jest dużo bardziej skomplikowany, niż się nam wydaje. No i działa leczniczo – ponieważ horrory mierzą się z tym, co wyparte i nieuświadomione. Są darmowym seansem psychoanalitycznym”.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "To jest problem, który wzruszająco i literacko rozpracowywał Dick. Do czasu Dicka mówiło się głównie o świadomości – że to jest ten graniczny fenomen, który czyni z nas ludzi – nasza świadomość, świadomość siebie samego. Dick poszedł dalej – dla niego to, co „ludzkie” wiąże się już nie ze świadomością (wszak dziś wiemy, że świadomością mogą poszczycić się także niektóre byty nie-ludzkie, jak zwierzęta), ale ze zdolnością do współodczuwania (chociaż tę zdolność dzielimy ze zwierzętami). Empatia, współodczuwanie, utożsamianie się z innym człowiekiem – to czyni nas człowiekiem, mówi Dick. Nie szybkość myślenia, używanie narzędzi czy język. Te próby definiowania tego, czym jest człowiek najprawdopodobniej w przyszłości bardzo się zintensyfikują wobec wyzwań związanych ze sztuczną inteligencją, ale także z powodu głębokiej zmiany naszego stosunku do zwierząt, i zmienią generalnie całość naszej wizji świata. Tak, zwierzętom pękają serca z żalu czy rozpaczy. Jak to będzie AI – nie wiem. Do tej pory nie zawiesił się z rozpaczy żaden wojskowy komputer i żaden militarny dron zabijający ludzi z powietrza nie rozpadł się z powodu poczucia winy.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "W czasach totalnego kryzysu, wojny, niepokoju społecznego, wszystko ma tendencję do powrotu prostych czy nawet prostackich porządków. Wygląda na to, że długi czas względnego spokoju po II wojnie światowej kończy się i być może pójdą w niepamięć te wszystkie społeczne zdobycze ostatnich pięćdziesięciu lat. Kobiety wrócą do darcia szarpi, zwierzęta znów staną się mięsem, tradycyjna rodzina stanie się jedyną wyobrażalną podstawową „komórką społeczną”, wyzysk jedyną wyobrażalną ekonomią, a przemoc jedyną wyobrażalną polityką. Boję się, że za kilka lat zdamy sobie sprawę, że żyliśmy w dobrych czasach, które bezpowrotnie minęły.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "W ogóle nie rozumiem fenomenu literatury gatunkowej. Dla mnie istnieje tylko literatura źle i dobrze napisana, temat jest kwestią drugorzędną. Mam też wrażenie, że ten podział powoli się kończy i rynek książki zaczyna się bardziej demokratyzować. Czytelnik bardziej wyrobiony i mający jakiś gust literacki będzie szukał czegoś, co jest dobrze zrobione i co daje do myślenia bez względu na to, jak to jest klasyfikowane.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wielu ludzi uważa fantastykę za coś zmyślonego, a przez to niepełnowartościowego. Często na spotkaniach autorskich ludzie pytają mnie, czy to, co napisałam to prawda. To bardzo naiwne pytanie. Zadaniem literatury nie jest odzwierciedlanie „prawdy” – od tego są media, nauka, dziennikarstwo, reportaż… Literatura to pokazywanie całości doświadczenia człowieka – z jego snami, ideami, możliwościami, projektami, lękami i obawami (…) Uważam, że ten nurt powinien walczyć o swoje i zniwelować niesłuszne uprzedzenia. Literatura – jakakolwiek – jeśli chce aspirować do mainstreamu i związanego z tym powodzenia musi być porządnie napisana i może mniej hermetyczna. Ważne jest, jak Autor czy Autorka myśli o swoim tekście i dla kogo ten tekst pisze. Jeśli pisze dla grupy znajomych otrzaskanych z tematem, to nie ma się co dziwić, że skazuje swoją książkę na marginalność.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wprowadzenie religii do szkół uczyniło wiele złego, niwelując różnicę pomiędzy faktami naukowymi a aktami wiary. Od ponad 20 lat dzieci uczą się jednocześnie, lekcja w lekcję, o grawitacji i zmartwychwstaniu. To tworzy umysły podatne na wszelkie poznawcze manipulacje. W świecie postprawdy takie umysły są bezradne, tracą orientację. Stąd rosną w siłę dwa narodowe grzechy – hipokryzja i konformizm. Hipokryzja jako najprostszy sposób utrzymywania podstawowej spójności poznawczej, a konformizm jako skutek nieumiejętności samodzielnego myślenia. W dzisiejszym chaotycznym świecie widzimy, jak ideologie oparte na religiach próbują wprowadzić swój porządek, który jest w istocie porządkiem wykluczenia – kobiet, obcych, inaczej myślących. Tylko laickie państwo jest w stanie przeciwstawić się temu.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Współczesny świat przypomina to, o czym pisał Kartezjusz, przedstawiając obraz rozciągłego pola materii – chłodnej, mechanicznej, nieprzyjaznej człowiekowi. Poruszamy się po tym polu uzbrojeni w takie czy inne zdolności, w talenty i we własną pracowitość, próbując wydeptać tu swoje ścieżki, znaleźć miejsce dla siebie i robić to co naprawdę chcielibyśmy. Ale tylko nielicznym z nas się to udaje. Dziś zbyt wielu ludzi stało się niewolnikami innych, jakkolwiek określenie „niewolnik” znaczy obecnie coś zupełnie innego, niż znaczyło kiedyś. Praca, która nie zaspokaja ambicji, ani nie odpowiada zainteresowaniom, która jest czymś narzuconym i budzącym wstręt, którą postrzega się jak harówkę, która napycha portfele raczej pracodawców, a nie własne, którą musi się wykonywać, żeby przeżyć – to jest współczesne niewolnictwo. Dość powszechna jest wiara (a może złudzenie?), że pozycja artysty, w tym i pisarza, pozwala przebić się poza klasę społeczną i zawiłe zależności pracy najemnej – stąd dążność by taką pozycję osiągnąć.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zakazałabym używania pięknego słowa „solidarność” społeczeństwu, które odmówiło pomocy uchodźcom.", Author = "Olga Tokarczuk" },
        };
    }
}